node <<'EOF'
const fs = require('fs'), path = require('path');
const files = [];
for (const dir of ['src', 'test']) {
  for (const f of fs.readdirSync(dir)) if (f.endsWith('.js')) files.push(path.join(dir, f));
}
let renamed = 0, bumped = 0;
for (const f of files) {
  const before = fs.readFileSync(f, 'utf8');
  let after = before.replace(/\bretryPolicy\b/g, () => { renamed++; return 'backoffPolicy'; });
  after = after.replace(/\bmaxAttempts: 3(?!\d)/g, () => { bumped++; return 'maxAttempts: 5'; });
  if (after !== before) fs.writeFileSync(f, after);
}
console.log(`files scanned: ${files.length}, retryPolicy renamed: ${renamed}, maxAttempts 3->5: ${bumped}`);
EOF
echo "--- remaining:"; grep -rn "retryPolicy\|maxAttempts: 3\b" src test; echo "(end)"; echo "--- tests:"; node --test 2>&1 | tail -n 12

